import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtemp,mkdir,writeFile,readFile,rm} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {DatabaseSync} from 'node:sqlite';
import {importCatalogBundle} from '../scripts/import-catalog-bundle.js';
import {createProductService} from '../server/product-service.js';
async function fixture(t){const folder=await mkdtemp('/tmp/catalog-bundle-');t.after(()=>rm(folder,{recursive:true,force:true}));await mkdir(folder+'/imports');const csv='code,name\nTST001.OF,测试目录甲\nTST002.OF,测试目录乙\n';await writeFile(folder+'/imports/fund.csv',csv);const manifest={version:1,total:2,files:[{file:'fund.csv',category:'fund',rows:2,sha256:createHash('sha256').update(csv).digest('hex')}]};await writeFile(folder+'/imports/manifest.json',JSON.stringify(manifest));return {folder,manifest,save:()=>writeFile(folder+'/imports/manifest.json',JSON.stringify(manifest))}}
test('离线目录先校验再入库，备份包含旧产品，重复导入按代码更新且不联网',async t=>{const x=await fixture(t);const s=createProductService({folder:x.folder,defaults:false});await s.importCatalog([{code:'OLD.YH',name:'保留原目录',category:'bank'},{code:'TST001.OF',name:'旧名称',category:'fund',issuer:'已核对机构',riskLevel:'R3',type:'mixed',currency:'CNY'}]);s.close();const result=await importCatalogBundle({folder:x.folder});assert.equal(result.imported,2);assert.equal(result.totalProducts,3);assert.equal(result.networkRequests,0);const backup=new DatabaseSync(result.backup,{readOnly:true});assert.equal(backup.prepare('SELECT count(*) n FROM products').get().n,2);backup.close();const r=await importCatalogBundle({folder:x.folder});assert.equal(r.totalProducts,3);const restored=createProductService({folder:x.folder,defaults:false});const found=await restored.catalog({search:'测试目录甲'});assert.equal(found.items[0].name,'测试目录甲');assert.equal(found.items[0].riskLevel,'R3');assert.equal(found.items[0].type,'mixed');assert.equal(found.items[0].issuer,'已核对机构');restored.close()});
test('清单哈希、条数、类别和路径校验失败均在写库之前停止',async t=>{for(const mutate of [m=>m.files[0].sha256='0'.repeat(64),m=>m.files[0].rows=3,m=>m.files[0].category='unknown',m=>m.files[0].file='../fund.csv',m=>m.total=3]){const x=await fixture(t);mutate(x.manifest);await x.save();await assert.rejects(()=>importCatalogBundle({folder:x.folder}));await assert.rejects(()=>readFile(x.folder+'/finance.sqlite'),{code:'ENOENT'})}});
test('跨文件重复代码会拒绝整包，不能重复覆盖或虚增数量',async t=>{const x=await fixture(t);await writeFile(x.folder+'/imports/duplicate.csv',await readFile(x.folder+'/imports/fund.csv'));x.manifest.files.push({...x.manifest.files[0],file:'duplicate.csv'});x.manifest.total=4;await x.save();await assert.rejects(()=>importCatalogBundle({folder:x.folder}),/重复代码/);await assert.rejects(()=>readFile(x.folder+'/finance.sqlite'),{code:'ENOENT'})});
test('明确替换只删除清单指定且名称类别相符的旧目录产品，保留历史行情与其他类别',async t=>{const x=await fixture(t);x.manifest.removeProducts=[{code:'RETIRED.SH',name:'旧REIT',category:'fund'}];await x.save();const s=createProductService({folder:x.folder,defaults:false});await s.importCatalog([{code:'RETIRED.SH',name:'旧REIT',category:'fund'},{code:'KEEP.YH',name:'保留银行',category:'bank'}]);s.close();const db=new DatabaseSync(x.folder+'/finance.sqlite');db.prepare('INSERT INTO observations VALUES(?,?,?,?,?,?,?)').run('test','RETIRED.SH','basis','2026-01-01',1,'{}','2026-01-01');db.close();const a=await importCatalogBundle({folder:x.folder});assert.equal(a.removed,1);assert.equal(a.totalProducts,3);const check=new DatabaseSync(x.folder+'/finance.sqlite',{readOnly:true});assert.equal(check.prepare('SELECT count(*) n FROM observations').get().n,1);assert.equal(check.prepare("SELECT count(*) n FROM products WHERE code='KEEP.YH'").get().n,1);check.close();const b=await importCatalogBundle({folder:x.folder});assert.equal(b.removed,0);assert.equal(b.totalProducts,3)});
test('删除清单不能与新目录重叠；旧产品被用户修改时回滚本次全部删除',async t=>{const x=await fixture(t);x.manifest.removeProducts=[{code:'TST001.OF',name:'测试目录甲',category:'fund'}];await x.save();await assert.rejects(()=>importCatalogBundle({folder:x.folder}),/冲突/);await assert.rejects(()=>readFile(x.folder+'/finance.sqlite'),{code:'ENOENT'});x.manifest.removeProducts=[{code:'OLD1.SH',name:'旧一',category:'fund'},{code:'OLD2.SH',name:'旧二',category:'fund'}];await x.save();const s=createProductService({folder:x.folder,defaults:false});await s.importCatalog([{code:'OLD1.SH',name:'旧一',category:'fund'},{code:'OLD2.SH',name:'用户修改名称',category:'fund'}]);s.close();await assert.rejects(()=>importCatalogBundle({folder:x.folder}),/已被修改/);const check=new DatabaseSync(x.folder+'/finance.sqlite',{readOnly:true});assert.equal(check.prepare("SELECT count(*) n FROM products WHERE code LIKE 'OLD%'").get().n,2);check.close()});
test('仅已核对的已成立未到期J代码目录从其他资管迁入券商，全部基金和其他未知产品不误改',async t=>{const x=await fixture(t);const csv='code,name\nJ110002.OF,东方红先锋6号2期\nJH852135_1.OF,海通季季升A份额\n';await writeFile(x.folder+'/imports/unexpired.csv',csv);x.manifest.files.push({file:'unexpired.csv',originalFile:'全部(已成立、未到期).csv',category:'other',rows:2,sha256:createHash('sha256').update(csv).digest('hex')});x.manifest.total=4;await x.save();const s=createProductService({folder:x.folder,defaults:false});await s.importCatalog([{code:'J110002.OF',name:'东方红先锋6号2期',category:'other'},{code:'UNKNOWN.X',name:'未知类别资料',category:'other'}]);s.close();await importCatalogBundle({folder:x.folder});const r=createProductService({folder:x.folder,defaults:false});assert.equal((await r.catalog({search:'J110002.OF'})).items[0].category,'broker');assert.equal((await r.catalog({search:'JH852135_1.OF'})).items[0].category,'broker');assert.equal((await r.catalog({search:'TST001.OF'})).items[0].category,'fund');assert.equal((await r.catalog({search:'UNKNOWN.X'})).items[0].category,'other');r.close()});
